const cfg = $('Konfiguracja targetu').first().json;
const pages = $input.first().json.data ?? [];
const page = pages.find(p => (p.name ?? '').toLowerCase().includes(cfg.page_name_contains.toLowerCase()))
  ?? pages.find(p => p.instagram_business_account?.id)
  ?? pages[0];
if (!page?.access_token || !page.instagram_business_account?.id) throw new Error('Brak strony VIRYA, Page Access Token lub połączonego IG Business.');
const username = String(cfg.target_username).replace(/[^a-zA-Z0-9._]/g, '');
if (!username) throw new Error('Nieprawidłowy username.');
const fields = `business_discovery.username(${username}){id,username,name,biography,website,profile_picture_url,followers_count,follows_count,media_count,media.limit(5){id,caption,comments_count,like_count,media_type,media_product_type,permalink,timestamp}}`;
return [{json:{
  ig_user_id: page.instagram_business_account.id,
  source_ig_username: page.instagram_business_account.username ?? null,
  target_username: username,
  fields,
  page_access_token: page.access_token
}}];

const raw = $input.first().json.business_discovery;
if (!raw) throw new Error('Brak business_discovery w odpowiedzi.');
return [{json:{
  api_status: 'OK',
  access_mode: 'BUSINESS_DISCOVERY',
  target: {
    id: raw.id,
    username: raw.username,
    name: raw.name,
    biography: raw.biography,
    website: raw.website,
    profile_picture_url: raw.profile_picture_url,
    followers_count: raw.followers_count,
    follows_count: raw.follows_count,
    media_count: raw.media_count
  },
  recent_media: raw.media?.data ?? [],
  checked_at: new Date().toISOString(),
  security: 'No access token is included in this output.'
}}];
